INSERT OR IGNORE INTO appdata (key,value) VALUES ('catalog', '{"products":[{"id":101,"title":"Set de Congas LP Matador Wood 11\" Quinto y 12.5\" Tumbadora con Soporte Doble","category":"percusion","catLabel":"Percusión Latina, Congas","brand":"LP Latin Percussion","oldPrice":2290,"price":1890,"svg":"congas","section":"bestseller","desc":"El set LP Matador Wood combina cascos de roble de Siam de 3 capas con parches de cuero natural sin curtir y aros Soft Strike para un proyección cálida y potente en orquesta en vivo.","keySpecs":[["Diámetros","11\" Quinto + 12.5\" Conga"],["Material Casco","Roble de Siam 3 capas"],["Herrajes","Cromados + Soporte Doble"],["Parches","Cuero natural seleccionado"],["Altura","30 pulgadas profesional"],["Garantía","Garantía según fabricante en tienda"]],"stock":0,"image":""},{"id":102,"title":"Trompeta Profesional en Si Bemol (Bb) Yamaha YTR-2330 Lacado Dorado con Estuche Rígido","category":"vientos","catLabel":"Vientos y Metales, Trompetas","brand":"Yamaha","oldPrice":2390,"price":1950,"svg":"trumpet","section":"bestseller","desc":"La Yamaha YTR-2330 ofrece una entonación precisa, pistones de aleación Monel de alta durabilidad y campana de latón amarillo de dos piezas diseñada para salsa, ensambles y banda.","keySpecs":[["Afinación","Si Bemol (Bb)"],["Campana","123 mm Latón Amarillo"],["Pistones","Aleación Monel anticorrosión"],["Boquilla Incluida","Yamaha TR-11B4"],["Acabado","Lacado Dorado Brillante"],["Estuche","Case rígido original Yamaha"]],"stock":0,"image":""},{"id":103,"title":"Bajo Eléctrico Activo 5 Cuerdas Ibanez SR505E Soundgear con Pastillas Bartolini BH2","category":"bajos","catLabel":"Bajos Eléctricos, 5 Cuerdas","brand":"Ibanez","oldPrice":3150,"price":2690,"svg":"bass","section":"bestseller","desc":"El Ibanez SR505E es uno de los bajos de 5 cuerdas más utilizados en música latina y fusión gracias a sus pastillas Bartolini BH2, ecualizador activo de 3 bandas y mástil rápido de Jatoba/Nogal.","keySpecs":[["Configuración","5 Cuerdas Activo"],["Pastillas","2x Bartolini BH2 Dual-Coil"],["Ecualizador","Ibanez Custom 3-Band EQ"],["Cuerpo","Okoume acabado satinado"],["Mástil","5 piezas Jatoba / Nogal"],["Calibración","Incluida gratis en taller"]],"stock":0,"image":""},{"id":104,"title":"Piano Digital de Escenario Yamaha P-225B de 88 Teclas Contrapesadas GHC con Pedal","category":"teclados","catLabel":"Pianos y Teclados, Escenario","brand":"Yamaha","oldPrice":3090,"price":2590,"svg":"piano","section":"bestseller","desc":"El Yamaha P-225 incorpora el motor de sonido del piano de cola de concierto Yamaha CFX, teclado contrapesado GHC de 88 teclas e interfaz de audio USB integrada.","keySpecs":[["Teclado","88 Teclas Contrapesadas GHC"],["Motor de Sonido","Yamaha CFX Virtual Resonance"],["Polifonía Máx.","192 notas"],["Salidas","L/L+R 1/4\" + USB Audio/MIDI"],["Altavoces","2x (7W x 2) bidireccionales"],["Incluye","Pedal Sustain + Atril"]],"stock":0,"image":""},{"id":105,"title":"Timbales Profesionales LP Tito Puente 14\" y 15\" en Acero Inoxidable con Soporte y Campana","category":"percusion","catLabel":"Percusión Latina, Timbales","brand":"LP Latin Percussion","oldPrice":2490,"price":2090,"svg":"timbales","section":"new","desc":"Los timbales LP257-KP Tito Puente en acero inoxidable entregan un cáscara brillante y penetrante, acompañados de atril doble reforzado con inclinación ajustable y porta cencerro.","keySpecs":[["Vasos","14\" y 15\" Acero Inoxidable"],["Profundidad","6-1/2\" tradicional"],["Afinación","Tradicional por llaves"],["Soporte","Trípode doble cromado"],["Accesorios","Porta campana + Baquetas"],["Garantía","Garantía según fabricante LP"]],"stock":0,"image":""},{"id":106,"title":"Bongós Profesionales Meinl Marathon Designer Series Free Ride 7\" y 8.5\" Sunburst","category":"percusion","catLabel":"Percusión Latina, Bongós","brand":"Meinl","oldPrice":890,"price":690,"svg":"bongo","section":"new","desc":"Con el sistema patentado Free Ride Suspension de Meinl, los vasos de madera qued